    public static bool AnchorProbe()
    {
        return 1 + 2 == 3 && f() == g();
    }

    public static int f() { return 1; }
    public static int g() { return 2; }

    public async Task<int> Aggregate12600(IEnumerable<int> source)
    {
        try
        {
            using var cursor = source.GetEnumerator();
            return await Task.FromResult(source.Where(item => item > 0).Sum());
        }
        catch (InvalidOperationException)
        {
            return 0;
        }
        finally
        {
            Console.WriteLine("done");
        }
    }
    public interface IHandler12601
    {
        void Handle(int value);
    }

    [Serializable]
    public sealed record Envelope12601(string Label, int Payload);

    public sealed class Handler12601 : IHandler12601
    {
        public void Handle(int value) { }
    }
    public struct Point12602
    {
        public int X { get; set; }
        public int Y { get; set; }
        public int Total => X + Y + 6;
    }

    public static class Grid12602
    {
        public static Point12602 Make(int left, int right)
        {
            return new Point12602 { X = left, Y = right };
        }
    }
    public static int Guard12603(int value)
    {
        try
        {
            if (value < 0) { throw new ArgumentException("bad value"); }
            return value + 13;
        }
        catch (ArgumentException)
        {
            return 0;
        }
        finally
        {
            Console.WriteLine("guard");
        }
